import { endpoint, event, invoke, machine, mutation, on, query, ui } from '@hozu/core'
import { z } from 'zod'
import { home, login } from '../../routes.ts'

export const Session = z.object({ user: z.string() })
export const Name = z.object({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') })

export const SignIn = event({ payload: z.object({ name: z.string() }) })
export const SignOut = event({ payload: z.object({}) })
export const DeleteAccount = event({ payload: z.object({}) })

export const me = query({
  input: z.object({}),
  output: z.object({ name: z.string(), admin: z.boolean() }),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  runs: 'server',
})

export const signIn = mutation({ input: Name, output: z.object({}), runs: 'server' })
export const signOut = mutation({ input: z.object({}), output: z.object({}), runs: 'server' })
export const removeAccount = mutation({ input: z.object({}), output: z.object({}), runs: 'server' })

export const root = endpoint({ method: 'GET', path: '/', input: z.object({}), output: 'redirect' })

export const accountMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ name: z.string().nullable() }),
  }),
  initialContext: { draft: '', error: null, fields: { name: null } },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(SignIn, {
          target: 'signingIn',
          assign: (e) => { ctx.draft = e.name; ctx.error = null; ctx.fields = { name: null } },
        }),
        on(SignOut, { target: 'signingOut' }),
        on(DeleteAccount, { target: 'deletingAccount', assign: () => { ctx.error = null } }),
      ],
    },
    signingIn: {
      invoke: invoke(signIn, {
        input: { name: ctx.draft },
        done: { target: 'idle', navigate: () => ui.link(home, null) },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    signingOut: {
      invoke: invoke(signOut, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
    deletingAccount: {
      invoke: invoke(removeAccount, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null, { deleted: true }) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
  }),
})

import { contract, ui } from '@hozu/core'
import { admin, deleteAccount, login } from '../../routes.ts'
import { accountMachine, DeleteAccount, me, removeAccount, SignIn, SignOut, signIn, signOut } from './model.ts'
import { text } from './text.ts'

export const Login = ui.view({
  machine: accountMachine,
  route: login,
  render: ({ ctx, search, locale }) =>
    ui.main({ class: 'mx-auto max-w-sm space-y-6 px-4 py-16' }, [
      ui.h1({ class: 'text-3xl font-bold' }, [text.signIn]),
      ui.a({ href: locale === 'en' ? ui.alternate('de') : ui.alternate('en'), class: 'text-sm underline' }, [text.language]),
      search.deleted && ui.p({ role: 'status', class: 'rounded border bg-slate-50 px-4 py-2 text-sm' }, [text.accountDeleted]),
      ui.form({ class: 'space-y-3', on: { submit: ui.send(SignIn, { name: ui.dom.form('name') }) } }, [
        ui.label({ for: 'name', class: 'block text-sm font-medium' }, [text.name]),
        ui.input({
          id: 'name',
          name: 'name',
          required: true,
          minlength: 2,
          maxlength: 20,
          pattern: '[A-Za-z]{2,20}',
          autocomplete: 'username',
          'aria-invalid': ctx.fields.name !== null,
          'aria-describedby': 'name-error',
          class: 'w-full rounded border px-3 py-2',
        }),
        ui.p({ id: 'name-error', class: 'text-sm text-rose-600' }, [ctx.fields.name]),
        ui.button({ type: 'submit', class: 'w-full rounded bg-indigo-600 px-4 py-2 text-white' }, [text.signIn]),
      ]),
      ctx.error !== null && ui.p({ role: 'alert', class: 'text-rose-600' }, [ctx.error]),
    ]),
})

export const AccountBar = ui.view({
  machine: accountMachine,
  render: () =>
    ui.header({ class: 'mx-auto flex max-w-xl items-center justify-between px-4 pt-8 text-sm text-slate-600' }, [
      ui.query(
        me,
        {},
        {
          ready: (user) =>
            ui.div({ class: 'flex items-center gap-3' }, [
              ui.p({}, [text.signedInAs({ name: user.name })]),
              user.admin && ui.a({ href: ui.link(admin, null), class: 'underline' }, [text.admin]),
            ]),
          failed: { Unauthorized: () => ui.p({}, [text.signedOut]), Unexpected: () => ui.p({}, ['']) },
        },
      ),
      ui.form({ on: { submit: ui.send(SignOut, {}) } }, [
        ui.button({ type: 'submit', class: 'underline' }, [text.signOut]),
      ]),
    ]),
})

export const DeleteAccountPage = ui.view({
  machine: accountMachine,
  route: deleteAccount,
  render: ({ ctx }) =>
    ui.main({ class: 'mx-auto max-w-xl space-y-6 px-4 py-12' }, [
      ui.h1({ class: 'text-3xl font-bold' }, ['Delete account']),
      ui.p({ class: 'text-slate-600' }, ['This deletes all of your notes, archived ones included, and signs you out.']),
      ui.form({ on: { submit: ui.send(DeleteAccount, {}) } }, [
        ui.button({ type: 'submit', class: 'rounded bg-rose-600 px-4 py-2 text-white' }, ['Delete my account and notes']),
      ]),
      ctx.error !== null && ui.p({ role: 'alert', class: 'text-rose-600' }, [ctx.error]),
    ]),
})

export const signsIn = contract(accountMachine, {
  given: { state: 'idle' },
  when: [
    { send: SignIn, payload: { name: 'ada' } },
    { done: signIn, result: {} },
  ],
  expect: {
    state: 'idle',
    changes: { draft: 'ada' },
    effects: [{ effect: signIn, input: { name: 'ada' } }, { navigate: '/notes' }],
  },
})

export const signsOut = contract(accountMachine, {
  given: { state: 'idle' },
  when: [
    { send: SignOut, payload: {} },
    { done: signOut, result: {} },
  ],
  expect: { state: 'idle', effects: [{ effect: signOut, input: {} }, { navigate: '/login' }] },
})

export const deletesAccount = contract(accountMachine, {
  given: { state: 'idle' },
  when: [
    { send: DeleteAccount, payload: {} },
    { done: removeAccount, result: {} },
  ],
  expect: { state: 'idle', effects: [{ effect: removeAccount, input: {} }, { navigate: '/login?deleted=true' }] },
})

import { resolvers } from '@hozu/data'
import { app } from '@hozu/runtime-server'
import project from './hozu.config.ts'
import { notesResolvers } from './features/notes/server.ts'
import { accountResolvers } from './features/account/server.ts'
import { createUndoStore } from './features/notes/undo.ts'
import { createUserDirectory } from './features/account/users.ts'
import { createNoteStore } from './features/notes/store.ts'

const undo = createUndoStore()
const users = createUserDirectory()
const notes = createNoteStore()

export default app({
  resolvers: resolvers(project, (implement) => [
    ...accountResolvers(implement, undo, users, notes),
    ...notesResolvers(implement, undo, users, notes),
  ]),
})

// Everyone who has signed in, by lower-cased name, with the name they last signed in with.
export type UserDirectory = Map<string, string>

export const createUserDirectory = (): UserDirectory => new Map()

export const ADMIN = 'admin'

export const isAdmin = (session: { user: string }) => session.user.trim().toLowerCase() === ADMIN

import type { Implement } from '@hozu/data'
import { ui } from '@hozu/core'
import { home, login } from '../../routes.ts'
import { me, removeAccount, root, signIn, signOut } from './model.ts'
import { type UndoStore, undoKeyOf } from '../notes/undo.ts'
import { type UserDirectory, isAdmin } from './users.ts'
import { type NoteStore, purgeUser } from '../notes/store.ts'

export function accountResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  return [
    implement(me, (_, { session, fail }) => (session ? { name: session.user, admin: isAdmin(session) } : fail('Unauthorized', {}))),
    implement(root, (_, { session, redirect }) => redirect(session ? ui.link(home, null) : ui.link(login, null))),
    implement(signIn, ({ name }, { setSession }) => {
      setSession({ user: name.trim() })
      users.set(name.trim().toLowerCase(), name.trim())
      return {}
    }),
    implement(signOut, (_, { session, setSession }) => {
      if (session) undo.delete(undoKeyOf(session))
      setSession(null)
      return {}
    }),
    implement(removeAccount, (_, { session, setSession }) => {
      if (session) {
        const key = session.user.trim().toLowerCase()
        purgeUser(notes, key)
        users.delete(key)
        undo.delete(undoKeyOf(session))
      }
      setSession(null)
      return {}
    }),
  ]
}

import { endpoint, event, fn, invoke, machine, mutation, on, query, tag } from '@hozu/core'
import { z } from 'zod'

export const Note = z.object({
  id: z.string(),
  title: z.string(),
  body: z.string(),
  pinned: z.boolean(),
  createdAt: z.string(),
  sharedWith: z.array(z.string()),
  number: z.number().int(),
})
export const SharedNote = z.object({ id: z.string(), title: z.string(), owner: z.string() })
export const NoteKey = z.object({ id: z.string() })
export const NewNote = z.object({
  title: z.string().trim().min(1, 'Write a note').max(60, 'Use at most 60 characters'),
})
export const NoteEdit = z.object({
  title: z.string().trim().min(1, 'Write a title first').max(60, 'Use at most 60 characters'),
  body: z.string().trim().max(1000, 'Use at most 1000 characters in the body'),
})

export const Draft = event({ payload: z.object({ title: z.string() }) })
export const Add = event({ payload: z.object({ title: z.string() }) })
export const Remove = event({ payload: NoteKey })
export const Pin = event({ payload: NoteKey })
export const Search = event({ payload: z.object({ text: z.string() }) })
export const Edit = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const EditDraft = event({ payload: z.object({ title: z.string() }) })
export const Save = event({ payload: z.object({ id: z.string(), title: z.string() }) })
export const SaveDetail = event({ payload: z.object({ id: z.string(), title: z.string(), body: z.string() }) })
export const Cancel = event({ payload: z.object({}) })
export const Archive = event({ payload: NoteKey })
export const Restore = event({ payload: NoteKey })
export const Undo = event({ payload: z.object({}) })
export const Select = event({ payload: z.object({ id: z.string(), checked: z.boolean() }) })
export const Share = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const Unshare = event({ payload: z.object({ id: z.string(), name: z.string() }) })
export const Bulk = event({ payload: z.object({ ids: z.array(z.string()), action: z.string().nullable() }) })

export const notesTag = tag({ param: null })

export const ExportedNote = z.object({
  title: z.string(),
  pinned: z.boolean(),
  archived: z.boolean(),
  createdAt: z.string(),
})

export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({}),
  output: z.object({ user: z.string(), notes: z.array(ExportedNote) }),
  errors: { Unauthorized: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401 },
})

const IsArchived = { Archived: NoteKey }

export const NoteDetail = Note.extend({ archived: z.boolean() })

export const NoteNumber = z.object({ number: z.string() })

export const noteDetail = query({
  input: NoteNumber,
  output: NoteDetail,
  errors: { Unauthorized: z.object({}), NotFound: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const listNotes = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const addNote = mutation({
  input: NewNote,
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), TooMany: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const removeNote = mutation({
  input: NoteKey,
  output: NoteKey,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const renameNote = mutation({
  input: NoteKey.extend(NewNote.shape),
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const saveNote = mutation({
  input: NoteKey.extend(NoteEdit.shape),
  output: Note,
  errors: { Duplicate: z.object({ title: z.string() }), NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const togglePin = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const listArchived = query({
  input: z.object({}),
  output: z.array(Note),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const archiveNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const restoreNote = mutation({
  input: NoteKey,
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const lastDeleted = query({
  input: z.object({}),
  output: z.object({ title: z.string() }).nullable(),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const undoDelete = mutation({
  input: z.object({}),
  output: Note,
  errors: { NothingToUndo: z.object({}) },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const NoteKeys = z.object({ ids: z.array(z.string()).min(1, 'Select at least one note') })

export const removeNotes = mutation({
  input: NoteKeys,
  output: z.object({ ids: z.array(z.string()) }),
  errors: {},
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const archiveNotes = mutation({
  input: NoteKeys,
  output: z.object({ ids: z.array(z.string()) }),
  errors: {},
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const sharedNotes = query({
  input: z.object({}),
  output: z.array(SharedNote),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const UserNotes = z.object({ name: z.string(), notes: z.number().int() })

export const adminUsers = query({
  input: z.object({}),
  output: z.array(UserNotes),
  errors: { Unauthorized: z.object({}), Forbidden: z.object({}) },
  scope: 'user',
  freshness: 'request',
  tags: () => [notesTag()],
  runs: 'server',
})

export const shareNote = mutation({
  input: NoteKey.extend({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') }),
  output: Note,
  errors: { Self: z.object({}), NotFound: NoteKey, ...IsArchived },
  invalidates: () => [notesTag()],
  runs: 'server',
})

export const unshareNote = mutation({
  input: NoteKey.extend({ name: z.string() }),
  output: Note,
  errors: { NotFound: NoteKey },
  invalidates: () => [notesTag()],
  runs: 'server',
})

const matches = (item: { title: string }, text: string) =>
  item.title.toLowerCase().includes(text.trim().toLowerCase())

export const visibleNotes = fn({
  input: z.object({ items: z.array(Note), text: z.string() }),
  output: z.array(Note),
  impl: ({ items, text }) => items.filter((item) => matches(item, text)),
})

export const PAGE_SIZE = 5

const Selection = z.object({ items: z.array(Note), text: z.string(), limit: z.number() })

export const listedNotes = fn({
  input: Selection,
  output: z.array(Note),
  impl: ({ items, text, limit }) => items.filter((item) => matches(item, text)).slice(0, limit),
})

export const selectedCount = fn({
  input: Selection.omit({ limit: true }),
  output: z.number(),
  impl: ({ items, text }) => items.filter((item) => matches(item, text)).length,
})

export const hasMore = fn({
  input: Selection,
  output: z.boolean(),
  impl: ({ items, text, limit }) => items.filter((item) => matches(item, text)).length > limit,
})

export const addedOn = fn({
  input: z.object({ at: z.string() }),
  output: z.string(),
  impl: ({ at }) => at.slice(0, 10),
})

export const noteNumberParam = fn({
  input: z.object({ number: z.number() }),
  output: NoteNumber,
  impl: ({ number }) => ({ number: String(number) }),
})

export const noMatch = fn({
  input: z.object({ items: z.array(Note), text: z.string() }),
  output: z.boolean(),
  impl: ({ items, text }) => !items.some((item) => matches(item, text)),
})

export const DUPLICATE = 'duplicate'
export const NOT_FOUND = 'notFound'
export const ARCHIVED = 'archived'
export const TOO_MANY = 'tooMany'
export const NOTHING_TO_UNDO = 'nothingToUndo'
export const SELF_SHARE = 'selfShare'

export const notesMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ title: z.string().nullable() }),
    target: z.string(),
    shareName: z.string(),
    search: z.string(),
    editing: z.string(),
    editTitle: z.string(),
    editError: z.string().nullable(),
    selected: z.array(z.string()),
    busy: z.boolean(),
    detailTitle: z.string(),
    detailBody: z.string(),
    detailTitleError: z.string().nullable(),
    detailBodyError: z.string().nullable(),
    detailTouched: z.boolean(),
    saved: z.boolean(),
  }),
  initialContext: {
    draft: '',
    error: null,
    fields: { title: null },
    target: '',
    shareName: '',
    search: '',
    editing: '',
    editTitle: '',
    editError: null,
    selected: [],
    busy: false,
    detailTitle: '',
    detailBody: '',
    detailTitleError: null,
    detailBodyError: null,
    detailTouched: false,
    saved: false,
  },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(Draft, { target: 'idle', assign: (e) => { ctx.draft = e.title } }),
        on(Add, {
          target: 'adding',
          assign: (e) => {
            ctx.draft = e.title
            ctx.error = null
            ctx.fields = { title: null }
          },
        }),
        on(Select, { target: 'idle', guard: (e) => e.checked === true, assign: (e) => { ctx.selected.push(e.id) } }),
        on(Select, { target: 'idle', assign: (e) => { ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Bulk, {
          target: 'removingMany',
          guard: (e) => e.action === 'delete' && e.ids.length > 0,
          assign: (e) => { ctx.selected = e.ids; ctx.busy = true; ctx.error = null },
        }),
        on(Bulk, {
          target: 'archivingMany',
          guard: (e) => e.action === 'archive' && e.ids.length > 0,
          assign: (e) => { ctx.selected = e.ids; ctx.busy = true; ctx.error = null },
        }),
        on(Remove, { target: 'removing', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Restore, { target: 'restoring', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Archive, { target: 'archiving', assign: (e) => { ctx.target = e.id; ctx.error = null; ctx.selected = ctx.selected.filter((id) => id !== e.id) } }),
        on(Undo, { target: 'undoing', assign: () => { ctx.error = null } }),
        on(Share, { target: 'sharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Unshare, { target: 'unsharing', assign: (e) => { ctx.target = e.id; ctx.shareName = e.name; ctx.error = null } }),
        on(Pin, { target: 'pinning', assign: (e) => { ctx.target = e.id; ctx.error = null } }),
        on(Search, { target: 'idle', assign: (e) => { ctx.search = e.text } }),
        on(Edit, {
          target: 'idle',
          assign: (e) => {
            ctx.editing = e.id
            ctx.editTitle = e.title
            ctx.editError = null
            ctx.error = null
          },
        }),
        on(EditDraft, { target: 'idle', assign: (e) => { ctx.editTitle = e.title } }),
        on(Cancel, { target: 'idle', assign: () => { ctx.editing = ''; ctx.editTitle = ''; ctx.editError = null; ctx.error = null } }),
        on(Save, {
          target: 'saving',
          assign: (e) => {
            ctx.editing = e.id
            ctx.editTitle = e.title
            ctx.editError = null
            ctx.error = null
          },
        }),
        on(SaveDetail, {
          target: 'savingDetail',
          assign: (e) => {
            ctx.target = e.id
            ctx.detailTitle = e.title
            ctx.detailBody = e.body
            ctx.detailTitleError = null
            ctx.detailBodyError = null
            ctx.detailTouched = true
            ctx.saved = false
            ctx.error = null
          },
        }),
      ],
    },
    saving: {
      invoke: invoke(renameNote, {
        input: { id: ctx.editing, title: ctx.editTitle },
        done: { target: 'idle', assign: () => { ctx.editing = ''; ctx.editTitle = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.error = DUPLICATE } },
          Invalid: { target: 'idle', assign: (e) => { ctx.editError = e.fields.title } },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND; ctx.editing = '' } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED; ctx.editing = '' } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    savingDetail: {
      invoke: invoke(saveNote, {
        input: { id: ctx.target, title: ctx.detailTitle, body: ctx.detailBody },
        done: { target: 'idle', assign: () => { ctx.detailTouched = false; ctx.saved = true } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.detailTitleError = DUPLICATE } },
          Invalid: {
            target: 'idle',
            assign: (e) => { ctx.detailTitleError = e.fields.title; ctx.detailBodyError = e.fields.body },
          },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND; ctx.detailTouched = false } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED; ctx.detailTouched = false } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    adding: {
      invoke: invoke(addNote, {
        input: { title: ctx.draft },
        done: { target: 'idle', assign: () => { ctx.draft = '' } },
        failed: {
          Duplicate: { target: 'idle', assign: () => { ctx.error = DUPLICATE } },
          TooMany: { target: 'idle', assign: () => { ctx.error = TOO_MANY } },
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    removing: {
      invoke: invoke(removeNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    removingMany: {
      invoke: invoke(removeNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
        failed: {
          Invalid: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message; ctx.busy = false } },
        },
      }),
    },
    archivingMany: {
      invoke: invoke(archiveNotes, {
        input: { ids: ctx.selected },
        done: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
        failed: {
          Invalid: { target: 'idle', assign: () => { ctx.selected = []; ctx.busy = false } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message; ctx.busy = false } },
        },
      }),
    },
    pinning: {
      invoke: invoke(togglePin, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    sharing: {
      invoke: invoke(shareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          Self: { target: 'idle', assign: () => { ctx.error = SELF_SHARE } },
          Invalid: { target: 'idle', assign: (e) => { ctx.error = e.fields.name } },
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    unsharing: {
      invoke: invoke(unshareNote, {
        input: { id: ctx.target, name: ctx.shareName },
        done: { target: 'idle', assign: () => { ctx.shareName = '' } },
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    archiving: {
      invoke: invoke(archiveNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Archived: { target: 'idle', assign: () => { ctx.error = ARCHIVED } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    undoing: {
      invoke: invoke(undoDelete, {
        input: {},
        done: 'idle',
        failed: {
          NothingToUndo: { target: 'idle', assign: () => { ctx.error = NOTHING_TO_UNDO } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    restoring: {
      invoke: invoke(restoreNote, {
        input: { id: ctx.target },
        done: 'idle',
        failed: {
          NotFound: { target: 'idle', assign: () => { ctx.error = NOT_FOUND } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
  }),
})

import type { Implement } from '@hozu/data'
import { adminUsers, addNote, exportNotes, archiveNote, archiveNotes, removeNotes, lastDeleted, listArchived, listNotes, noteDetail, removeNote, renameNote, restoreNote, saveNote, shareNote, sharedNotes, togglePin, undoDelete, unshareNote } from './model.ts'
import { type Item, type UndoStore, undoKeyOf } from './undo.ts'
import { type UserDirectory, isAdmin } from '../account/users.ts'
import { nextNumber, type NoteStore } from './store.ts'

const view = ({ archived: _, ...item }: Item) => ({ ...item, sharedWith: [...item.sharedWith] })

export function notesResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  const { notes: store, owners, added } = notes
  const keyOf = (session: { user: string }) => session.user.toLowerCase()
  const listOf = (session: { user: string } | null): Item[] => (session ? (store.get(keyOf(session)) ?? []) : [])
  const ownListOf = (session: { user: string } | null) => {
    if (!session) return []
    const list = store.get(keyOf(session)) ?? []
    store.set(keyOf(session), list)
    return list
  }
  // Times of the adds that went through, per user: at most ADD_LIMIT within ADD_WINDOW_MS.
  const ADD_LIMIT = 10
  const ADD_WINDOW_MS = 60_000
  const recentAdds = (session: { user: string }, now: number) => {
    const times = (added.get(keyOf(session)) ?? []).filter((at) => now - at < ADD_WINDOW_MS)
    added.set(keyOf(session), times)
    return times
  }
  const forget = (session: { user: string } | null) => {
    if (session) undo.delete(undoKeyOf(session))
  }
  return [
    implement(adminUsers, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      if (!isAdmin(session)) return fail('Forbidden', {})
      const keys = new Set([...users.keys(), ...[...store].filter(([, items]) => items.length > 0).map(([key]) => key)])
      return [...keys]
        .map((key) => ({ name: users.get(key) ?? owners.get(key) ?? key, notes: store.get(key)?.length ?? 0 }))
        .sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()))
    }),
    implement(noteDetail, ({ number }, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const n = Number(number)
      if (!Number.isInteger(n)) return fail('NotFound', {})
      const item = listOf(session).find((entry) => entry.number === n)
      if (!item) return fail('NotFound', {})
      return { ...view(item), archived: item.archived }
    }),
    implement(listNotes, (_, { session, fail }) =>
      session
        ? [...listOf(session).filter((item) => !item.archived && item.pinned), ...listOf(session).filter((item) => !item.archived && !item.pinned)].map(view)
        : fail('Unauthorized', {}),
    ),
    implement(exportNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      const own = listOf(session)
      return {
        user: session.user,
        notes: [...own.filter((item) => item.pinned), ...own.filter((item) => !item.pinned)].map((item) => ({
          title: item.title,
          pinned: item.pinned,
          archived: item.archived,
          createdAt: new Date(item.createdAt).toISOString(),
        })),
      }
    }),
    implement(listArchived, (_, { session, fail }) =>
      session
        ? listOf(session).filter((item) => item.archived).sort((a, b) => b.createdAt.localeCompare(a.createdAt)).map(view)
        : fail('Unauthorized', {}),
    ),
    implement(sharedNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const me = keyOf(session)
      return [...store].flatMap(([owner, items]) =>
        owner === me
          ? []
          : items
              .filter((item) => !item.archived && item.sharedWith.some((name) => name.toLowerCase() === me))
              .map((item) => ({ id: item.id, title: item.title, owner: owners.get(owner) ?? owner })),
      )
    }),
    implement(shareNote, ({ id, name }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!session || !item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = name.trim()
      if (clean.toLowerCase() === keyOf(session)) return fail('Self', {})
      owners.set(keyOf(session), session.user.trim())
      if (!item.sharedWith.some((entry) => entry.toLowerCase() === clean.toLowerCase())) item.sharedWith.push(clean)
      return view(item)
    }),
    implement(unshareNote, ({ id, name }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      item.sharedWith = item.sharedWith.filter((entry) => entry.toLowerCase() !== name.trim().toLowerCase())
      return view(item)
    }),
    implement(archiveNote, ({ id }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.archived = true
      forget(session)
      return view(item)
    }),
    implement(restoreNote, ({ id }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id && entry.archived)
      if (!item) return fail('NotFound', { id })
      item.archived = false
      forget(session)
      return view(item)
    }),
    implement(addNote, ({ title }, { fail, session }) => {
      const items = ownListOf(session)
      if (!session) return fail('Invalid', { message: 'Signed out', fields: { title: 'Sign in first' } })
      const clean = title.trim()
      if (items.some((item) => item.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      const now = Date.now()
      const times = recentAdds(session, now)
      if (times.length >= ADD_LIMIT) return fail('TooMany', {})
      times.push(now)
      const item = { id: notes.nextId(), title: clean, body: '', pinned: false, createdAt: new Date().toISOString(), archived: false, sharedWith: [], number: nextNumber(notes, keyOf(session)) }
      items.unshift(item)
      forget(session)
      return view(item)
    }),
    implement(removeNote, ({ id }, { fail, session }) => {
      const items = ownListOf(session)
      const at = items.findIndex((item) => item.id === id)
      if (at < 0) return fail('NotFound', { id })
      if (items[at]?.archived) return fail('Archived', { id })
      const [item] = items.splice(at, 1)
      if (session && item) undo.set(undoKeyOf(session), { item, at })
      return { id }
    }),
    implement(removeNotes, ({ ids }, { session }) => {
      const items = ownListOf(session)
      const removed = items.filter((item) => ids.includes(item.id) && !item.archived).map((item) => item.id)
      for (const id of removed) items.splice(items.findIndex((item) => item.id === id), 1)
      forget(session)
      return { ids: removed }
    }),
    implement(archiveNotes, ({ ids }, { session }) => {
      const archived = listOf(session).filter((item) => ids.includes(item.id) && !item.archived)
      for (const item of archived) item.archived = true
      forget(session)
      return { ids: archived.map((item) => item.id) }
    }),
    implement(lastDeleted, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const entry = undo.get(undoKeyOf(session))
      return entry ? { title: entry.item.title } : null
    }),
    implement(undoDelete, (_, { fail, session }) => {
      const entry = session ? undo.get(undoKeyOf(session)) : undefined
      if (!session || !entry) return fail('NothingToUndo', {})
      const items = ownListOf(session)
      items.splice(Math.min(entry.at, items.length), 0, entry.item)
      forget(session)
      return view(entry.item)
    }),
    implement(renameNote, ({ id, title }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      forget(session)
      return view(item)
    }),
    implement(saveNote, ({ id, title, body }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      item.body = body.trim()
      forget(session)
      return view(item)
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      forget(session)
      return view(item)
    }),
  ]
}

import type { Item } from './undo.ts'

// Every user's notes, by lower-cased name, with who shared them and when they added them.
export type NoteStore = {
  notes: Map<string, Item[]>
  // Display name of each owner who has shared a note, by store key.
  owners: Map<string, string>
  // Times of the adds that went through, per user.
  added: Map<string, number[]>
  // Highest note number ever assigned to a user, so numbers are never reused.
  numbers: Map<string, number>
  nextId: () => string
}

export function createNoteStore(): NoteStore {
  let seq = 0
  const nextId = () => `n${++seq}`
  // Entries are given newest first; numbers are assigned oldest first so the first entry ever added is No. 1.
  const seed = (notes: [string, string][]) =>
    notes.map(([title, createdAt], i) => ({
      id: nextId(),
      title,
      body: '',
      pinned: false,
      createdAt,
      archived: false,
      sharedWith: [] as string[],
      number: notes.length - i,
    }))
  const ada = seed([['Buy milk', '2026-01-15T09:00:00.000Z'], ['Call Bob', '2026-01-14T09:00:00.000Z']])
  const bob = seed([["Bob's secret", '2026-01-10T09:00:00.000Z']])
  return {
    notes: new Map<string, Item[]>([
      ['ada', ada],
      ['bob', bob],
    ]),
    owners: new Map(),
    added: new Map(),
    numbers: new Map([
      ['ada', ada.length],
      ['bob', bob.length],
    ]),
    nextId,
  }
}

// The next note number for a user: one past the highest ever assigned to them, never reused.
export const nextNumber = (store: NoteStore, key: string) => {
  const n = (store.numbers.get(key) ?? 0) + 1
  store.numbers.set(key, n)
  return n
}

// Drops everything kept for a user: their notes (archived and shared ones included), sharing, add history and numbering.
export const purgeUser = (store: NoteStore, key: string) => {
  store.notes.delete(key)
  store.owners.delete(key)
  store.added.delete(key)
  store.numbers.delete(key)
}

