      if (!isAdmin(session)) return fail('Forbidden', {})
      const keys = new Set([...users.keys(), ...[...store].filter(([, items]) => items.length > 0).map(([key]) => key)])
      return [...keys]
        .map((key) => ({
          name: users.get(key)?.name ?? owners.get(key) ?? key,
          notes: store.get(key)?.length ?? 0,
          readOnly: key === ADMIN ? false : (users.get(key)?.readOnly ?? false),
        }))
        .sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()))
    }),
    implement(setAccountAccess, ({ name, access }, { session, fail }) => {
      if (!session || !isAdmin(session)) return fail('Forbidden', {})
      const key = name.trim().toLowerCase()
      if (key === ADMIN) return fail('Forbidden', {})
      const existing = users.get(key)
      users.set(key, { name: existing?.name ?? name.trim(), readOnly: access === 'readOnly' })
